using System.Numerics;
using System.Runtime.InteropServices;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD with multiple accumulators.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count * 4)
        {
            var vecs = MemoryMarshal.Cast<float, Vector<float>>(values);
            int vecLen = vecs.Length;
            int unrolled = vecLen & ~3; // round down to multiple of 4

            // Four independent accumulators to hide multiply latency
            var acc0 = Vector<float>.One;
            var acc1 = Vector<float>.One;
            var acc2 = Vector<float>.One;
            var acc3 = Vector<float>.One;

            int vi = 0;
            for (; vi < unrolled; vi += 4)
            {
                acc0 *= vecs[vi];
                acc1 *= vecs[vi + 1];
                acc2 *= vecs[vi + 2];
                acc3 *= vecs[vi + 3];
            }

            for (; vi < vecLen; vi++)
                acc0 *= vecs[vi];

            acc0 *= acc1;
            acc2 *= acc3;
            acc0 *= acc2;

            // Horizontal reduction
            float product = 1f;
            for (int lane = 0; lane < Vector<float>.Count; lane++)
                product *= acc0[lane];

            // Scalar tail
            i = vecLen * Vector<float>.Count;
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4-way unroll
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int limit = values.Length & ~3;
        for (; i < limit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        for (; i < values.Length; i++)
            p0 *= values[i];

        return p0 * p1 * p2 * p3;
    }
}

